-- build_cohort_covariates.sql — export clinical covariates and outcomes from PostgreSQL.
-- Run psql FROM YOUR DATA DIRECTORY: the \copy output is relative to the working directory.
--   cd /path/to/data && psql -d mimic -f build_cohort_covariates.sql
\copy (with co as (select d.subject_id, d.hadm_id, d.stay_id, d.gender, d.admission_age, d.race, d.icu_intime, d.icu_outtime, d.los_icu, d.los_hospital, d.first_icu_stay, s.suspected_infection_time, s.sofa_score as sepsis_sofa, fd.sofa as sofa_fd, si.sapsii, oa.oasis, ap.apsiii, ch.charlson_comorbidity_index, l.creatinine_max, l.bun_max, l.wbc_max, l.hemoglobin_min, l.platelets_min, l.bilirubin_total_max, l.bicarbonate_min, l.sodium_min, l.potassium_max, l.inr_max, l.alt_max, v.heart_rate_mean, v.mbp_min, v.mbp_mean, v.resp_rate_mean, v.temperature_mean, v.spo2_min, u.urineoutput as urineoutput_fd, d.hospital_expire_flag, d.dischtime, d.dod from mimiciv_derived.icustay_detail d join mimiciv_derived.sepsis3 s on s.stay_id = d.stay_id and s.sepsis3 left join mimiciv_derived.first_day_sofa fd on fd.stay_id = d.stay_id left join mimiciv_derived.sapsii si on si.stay_id = d.stay_id left join mimiciv_derived.oasis oa on oa.stay_id = d.stay_id left join mimiciv_derived.apsiii ap on ap.stay_id = d.stay_id left join mimiciv_derived.charlson ch on ch.subject_id = d.subject_id and ch.hadm_id = d.hadm_id left join mimiciv_derived.first_day_lab l on l.stay_id = d.stay_id left join mimiciv_derived.first_day_vitalsign v on v.stay_id = d.stay_id left join mimiciv_derived.first_day_urine_output u on u.stay_id = d.stay_id), tob as (select co.stay_id, max(cm.troponin_t) as troponin_t_max_24h from co join mimiciv_derived.cardiac_marker cm on cm.hadm_id = co.hadm_id and cm.charttime between co.icu_intime and co.icu_intime + interval '24 hour' group by co.stay_id), vaso as (select co.stay_id, max(n.norepinephrine_equivalent_dose) as norepi_eq_max_24h from co join mimiciv_derived.norepinephrine_equivalent_dose n on n.stay_id = co.stay_id group by co.stay_id), vent as (select co.stay_id, bool_or(vv.ventilation_status = 'InvasiveVent') as invasive_vent_24h from co join mimiciv_derived.ventilation vv on vv.stay_id = co.stay_id and vv.starttime between co.icu_intime and co.icu_intime + interval '24 hour' group by co.stay_id), rr as (select co.stay_id, bool_or(r.dialysis_active = 1) as rrt_7d from co join mimiciv_derived.rrt r on r.stay_id = co.stay_id and r.charttime between co.icu_intime and co.icu_intime + interval '7 day' group by co.stay_id) select co.*, fb.lactate_max as lactate_max_fd, tob.troponin_t_max_24h, vaso.norepi_eq_max_24h, vent.invasive_vent_24h, rr.rrt_7d from co left join mimiciv_derived.first_day_bg fb on fb.stay_id = co.stay_id left join tob on tob.stay_id = co.stay_id left join vaso on vaso.stay_id = co.stay_id left join vent on vent.stay_id = co.stay_id left join rr on rr.stay_id = co.stay_id) to 'cohort_covariates.csv' csv header
